<script lang="ts">
import { onMount } from 'svelte';
import ContextLens from '$lib/FP2ContextLens.svelte';
import { base } from '$app/paths';
import { geoMercator, geoPath } from 'd3-geo';
import { countInScope, type NeighborhoodGeoJSON } from '$lib/analytics';
import { normalizedCount, spearman } from '$lib/fp2.mjs';
type Metric = { value: number; period: string; reliability: string; percentMoe: number | null; n?: number; table: string };
type Context = { name: string; population: { estimate: number; moe: number; period: string } | null; metrics: Record<string, Metric | null>; eligibleSales: number };
type Summary = { total: number; days: { day: number; count: number }[]; events: { id: string; season: string; total: number; days: { day: number; count: number }[] }[] };
let geography: NeighborhoodGeoJSON | null = null;
let summary: Summary | null = null;
let context: Context[] = [];
let error = '';
let event = 'all', day = 0, mode = 'count', metric = 'poverty', selected = 'Marcy Holmes';
let lower = 0, upper = 100, step = 1;
const metrics: Record<string, { label: string; period: string; unit: string; explanation: string }> = {
 traffic: {label:'Median sampled-site AADT',period:'MnDOT 2024',unit:'veh/day',explanation:'Median annual average daily traffic across at least three matched sampled sites. Includes measured and modeled records; it is not total neighborhood traffic or snow-day exposure.'},
 poverty: { label: 'People below poverty', period: 'ACS 2019–2023', unit: '%', explanation: 'People below the poverty threshold, divided by people for whom poverty status is determined.' },
 lowIncome: { label: 'Households earning under $35k', period: 'ACS 2019–2023', unit: '%', explanation: 'Households in the two income brackets below $35,000, divided by all households. This is not per-capita income.' },
 renters: { label: 'Renter households', period: 'ACS 2020–2024', unit: '%', explanation: 'Renter-occupied households as a share of occupied housing units.' },
 noVehicle: { label: 'Households without a vehicle', period: 'ACS 2020–2024', unit: '%', explanation: 'Households with no vehicle available. This describes vehicle access, not traffic volume or curbside parking demand.' },
 salePrice: { label: 'Median residential sale price', period: '2024 transactions', unit: '$', explanation: 'Median adjusted price of qualifying one-unit home, condo and townhouse sales in 2024. Single-parcel, non-land transactions included in the city ratio study; at least 10 sales per neighborhood.' }
};
const number = (v: number | null | undefined, digits = 0) => v == null || !Number.isFinite(v) ? '—' : v.toLocaleString('en-US', { maximumFractionDigits: digits });
$: xLabel = ((key: string) => (v: number) => metrics[key].unit === '$' ? '$' + number(v / 1000) + 'k' : metrics[key].unit === 'veh/day' ? number(v) : number(v, 1) + '%')(metric);
onMount(async () => {
 try {
  const values = await Promise.all(['neighborhoods.geojson','summary.json','fp2-context.json'].map(async url => {
   const response = await fetch(`${base}/data/${url}`);
   if (!response.ok) throw new Error(`Could not load ${url}`);
   return response.json();
  }));
  [geography, summary] = values; context = values[2].rows;
 } catch (e) { error = e instanceof Error ? e.message : 'Could not load data'; }
});
$: rows = (geography?.features ?? []).map(feature => {
 const info = context.find(c => c.name === feature.properties.name);
 const count = countInScope(feature.properties, event, day);
 const x = info?.metrics[metric]?.value ?? null;
 const y: number | null = normalizedCount(count, info?.population?.estimate, mode);
 return { feature, info, name: feature.properties.name, count, x, y };
});
$: maxX = Math.max(1, ...rows.map(r => r.x ?? 0)) * 1.06;
$: maxY = Math.max(1, ...rows.map(r => r.y ?? 0)) * 1.08;
$: minBound = maxX * lower / 100;
$: maxBound = maxX * upper / 100;
$: visible = rows.filter(r => r.x !== null && r.y !== null && r.x >= minBound && r.x <= maxBound);
$: visibleNames = new Set(visible.map(r => r.name));
$: rho = spearman(visible);
$: chosen = rows.find(r => r.name === selected);
$: selectionMetric = chosen?.info?.metrics[metric];
$: mapped = rows.reduce((s, r) => s + r.count, 0);
$: totalScope = event === 'all' ? summary : summary?.events.find(e => e.id === event);
$: total = day ? totalScope?.days.find(d => d.day === day)?.count ?? 0 : totalScope?.total ?? 0;
$: path = geography ? geoPath(geoMercator().fitExtent([[14,12],[386,494]], geography as any)) : null;
$: yTitle = mode === 'count' ? 'Observed tow records' : 'Records per 1,000 residents';
$: maxEvent = Math.max(1,...(summary?.events ?? []).map(e => chosen ? countInScope(chosen.feature.properties,e.id,day) : 0));
function color(y: number | null) {
 if (y === null) return 'url(#missing)';
 const t = Math.sqrt(y / maxY);
 return `rgb(${Math.round(224-203*t)},${Math.round(237-125*t)},${Math.round(232-117*t)})`;
}
function keyChoose(e: KeyboardEvent,name: string) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selected = name; } }
function story(next: number) { step=next; lower=0; upper=100; event='all'; day=0; mode=next===1?'count':'rate'; if(next===3)metric='poverty'; }
function reset() { event='all'; day=0; mode='count'; metric='poverty'; selected='Marcy Holmes'; lower=0; upper=100; step=1; }
</script>
<svelte:head><title>FP2 · Snow, streets &amp; neighborhoods</title><meta name="description" content="Explore neighborhood conditions and observed Minneapolis snow-emergency towing with linked maps, scatterplots and event histories." /></svelte:head>
<div class="fp2">
<header class="masthead"><a href={`${base}/`} class="wordmark"><span aria-hidden="true">✳</span> MINNEAPOLIS <small>DATA STORIES</small></a><nav aria-label="FP2 navigation"><a href="#explorer">Explore</a><a href="#methods">Sources &amp; methods</a><a href={`${base}/`}>Original dashboard ↗</a></nav><span class="edition">FP2 / PROOF OF CONCEPT</span></header>
<main>
<section class="intro"><div><p class="kicker">WINTER MOBILITY / NEIGHBORHOOD CONTEXT</p><h1>Snow, streets<br />&amp; <em>neighborhoods.</em></h1><p class="dek">Do neighborhood conditions track where snow-emergency towing is recorded?</p><p class="intro-note">Explore the geography first. Adjust for population. Then examine economic and housing patterns across the same neighborhoods.</p></div><aside class="sample-card"><span class="sample-tag">THE OBSERVED SAMPLE</span><strong>5,423</strong><span>tow records · 9 selected emergencies</span><div class="sample-grid"><div><b>87</b><span>neighborhoods</span></div><div><b>3</b><span>emergency days</span></div></div><p>2022/23, 2024/25 &amp; 2025/26 seasons<br />Selected events, not a complete city history.</p></aside></section>
<div class="story-steps" aria-label="Guided exploration">
{#each [{n:1,title:'Locate the concentration',text:'Start with observed counts.'},{n:2,title:'Account for population',text:'Compare records per 1,000 residents.'},{n:3,title:'Explore the association',text:'Inspect context, then vary event and day.'}] as item}<button class:active={step===item.n} aria-pressed={step===item.n} on:click={() => story(item.n)}><span class="step-number">0{item.n}</span><span><b>{item.title}</b><small>{item.text}</small></span><span class="step-arrow" aria-hidden="true">↗</span></button>{/each}
</div>
<section id="explorer" class="explorer" aria-label="Linked neighborhood explorer">
<div class="section-title"><div><p class="kicker">01 / EXPLORE THE RELATIONSHIP</p><h2>One city. Different neighborhood conditions.</h2></div><button class="reset" on:click={reset}>Reset exploration ↺</button></div>
{#if error}<p class="error" role="alert">{error}. Reload this page to try again.</p>{:else if !geography || !summary}<p role="status">Loading the documented neighborhood sample…</p>{:else}
<div class="controls">
<label>Snow emergency<select aria-label="Snow emergency" bind:value={event}><option value="all">All 9 selected events</option>{#each summary.events as e}<option value={e.id}>{e.id} · {e.season}</option>{/each}</select></label>
<label>Emergency phase<select aria-label="Emergency phase" bind:value={day}><option value={0}>All three days</option><option value={1}>Day 1</option><option value={2}>Day 2</option><option value={3}>Day 3</option></select></label>
<label>Towing measure<select aria-label="Towing measure" bind:value={mode}><option value="count">Observed records</option><option value="rate">Per 1,000 residents</option></select></label>
<label>Neighborhood indicator<select aria-label="Neighborhood indicator" bind:value={metric} on:change={() => {lower=0;upper=100;}}>{#each Object.entries(metrics) as [key,m]}<option value={key}>{m.label}</option>{/each}</select></label>
</div>
<div class="scope-line"><span><b>{number(mapped)}</b> mapped records <span class="separator">/</span> {number(total-mapped)} without a neighborhood in this scope</span><span>{metrics[metric].period} <span class="separator">·</span> Population: ACS 2020–2024</span></div>
<div class="linked-grid">
<article class="map-card"><div class="chart-heading"><h3>Where are the records?</h3><span>01 / MAP</span></div><p class="chart-note">Select a neighborhood to highlight it in every view.</p>
<svg class="city-map" viewBox="0 0 400 510" role="group" aria-label="Neighborhood towing map"><title>Observed towing by Minneapolis neighborhood</title><defs><pattern id="missing" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#f2f0e8"/><path d="M0 0L6 6" stroke="#a0a9a6"/></pattern></defs>
{#each rows as r (r.name)}<path d={path?.(r.feature as any) ?? ''} fill={color(r.y)} opacity={(lower>0 || upper<100) && !visibleNames.has(r.name)?0.18:1} stroke={selected===r.name?'#d45a30':'#fff'} stroke-width={selected===r.name?3:0.8} role="button" tabindex="0" aria-pressed={selected===r.name} aria-label={`${r.name}: ${number(r.y,1)} ${yTitle}. Select neighborhood.`} on:click={() => selected=r.name} on:keydown={e => keyChoose(e,r.name)}><title>{r.name} · {number(r.y,1)} {yTitle}</title></path>{/each}</svg>
<div class="legend"><span>0</span><div></div><span>{number(maxY,1)}</span></div><p class="chart-note legend-note">{yTitle} · hatched = unavailable denominator</p></article>
<article class="scatter-card"><div class="chart-heading"><h3>Does context track towing?</h3><span>02 / ASSOCIATION</span></div><p class="chart-note">Each dot is a neighborhood. Orange marks your selection.</p>
<svg class="scatter" viewBox="0 0 640 440" role="group" aria-label="Socioeconomic association scatterplot"><title>{metrics[metric].label} and {yTitle}</title>
{#each [0,1,2,3,4] as tick}<line x1="72" x2="610" y1={365-tick/4*310} y2={365-tick/4*310} stroke="#e0e6e2"/><text x="60" y={369-tick/4*310} text-anchor="end" class="axis-tick">{number(maxY*tick/4,1)}</text><text x={72+tick/4*538} y="390" text-anchor="middle" class="axis-tick">{xLabel(maxX*tick/4)}</text>{/each}
<text x="72" y="24" class="axis-label">{yTitle} ↑</text><text x="341" y="425" text-anchor="middle" class="axis-label">{metrics[metric].label} →</text>
{#each rows.filter(r => r.x!==null && r.y!==null).sort((a,b) => Number(a.name===selected)-Number(b.name===selected)) as r (r.name)}<circle cx={72+(r.x??0)/maxX*538} cy={365-(r.y??0)/maxY*310} r={selected===r.name?8:5} fill={selected===r.name?'#be4b25':'#23786d'} fill-opacity={visibleNames.has(r.name)?0.8:0.12} stroke={selected===r.name?'#5d2818':'#fff'} stroke-width={selected===r.name?2:0.7} role="button" tabindex="0" aria-pressed={selected===r.name} aria-label={`${r.name}: ${xLabel(r.x??0)}, ${number(r.y,1)} ${yTitle}`} on:click={() => selected=r.name} on:keydown={e => keyChoose(e,r.name)}><title>{r.name}: {xLabel(r.x??0)} · {number(r.y,1)} {yTitle}</title></circle>{/each}</svg>
<div class="brush"><div><b>Focus on an indicator range</b><span>{xLabel(minBound)} – {xLabel(maxBound)}</span></div><div class="sliders"><label>Lower bound<input type="range" min="0" max={upper} step="1" bind:value={lower} /></label><label>Upper bound<input type="range" min={lower} max="100" step="1" bind:value={upper} /></label><button on:click={() => {lower=0;upper=100;}}>Clear range</button></div></div>
<div class="relationship"><div><b>{rho===null?'—':rho.toFixed(2)}</b><span>Spearman ρ</span></div><p><strong>{visible.length} neighborhoods in range</strong><br />{rows.length-rows.filter(r => r.x!==null && r.y!==null).length} excluded for missing indicator or denominator. Rank association is descriptive; it does not establish cause.</p></div></article></div>
<div class="interpretation"><span aria-hidden="true">↳</span><p><strong>Read the pattern carefully.</strong> {metrics[metric].explanation} {mode==='rate'?'Population adjustment is a scale comparison, not an individual towing risk: vehicles may belong to visitors, and neighborhoods differ in parking exposure.':'Counts show concentration in this sample; larger resident or visiting populations may generate more records.'}</p></div>
<article class="detail-card" aria-label="Selected neighborhood detail"><div class="detail-head"><div><p class="kicker">03 / FOLLOW ONE NEIGHBORHOOD</p><h3 data-testid="selected-name">{selected}</h3></div><label>Choose neighborhood<select aria-label="Choose neighborhood" bind:value={selected}>{#each rows as r}<option value={r.name}>{r.name}</option>{/each}</select></label></div>
{#if chosen}<div class="detail-grid"><div class="numbers"><span>CURRENT SCOPE</span><strong>{number(chosen.y,1)}</strong><p>{yTitle.toLowerCase()}</p><dl><div><dt>Observed records</dt><dd>{number(chosen.count)}</dd></div><div><dt>Resident estimate</dt><dd>{number(chosen.info?.population?.estimate)}</dd></div><div><dt>Population 90% MOE</dt><dd>± {number(chosen.info?.population?.moe)}</dd></div><div><dt>{metrics[metric].label}</dt><dd>{selectionMetric?xLabel(selectionMetric.value):'Unavailable'}</dd></div></dl><p class="detail-note">{selectionMetric?`${selectionMetric.period} · ${selectionMetric.reliability}`:metric==='salePrice'?`${chosen.info?.eligibleSales??0} qualifying sales; at least 10 required.`:'No matched ACS estimate. Missing values remain unavailable.'}{selectionMetric?.percentMoe!=null?` · Published 90% share MOE: ±${number(selectionMetric.percentMoe,1)} percentage points.`:''}{selectionMetric?.n?` · n = ${selectionMetric.n} sales.`:''}</p>{#if mode==='rate' && chosen.info?.population && chosen.info.population.estimate<500}<p class="detail-note">Small denominator: fewer than 500 estimated residents. A few records can produce a large per-resident value.</p>{/if}{#if !visibleNames.has(selected)}<p class="detail-note">This selection is outside the active indicator range or has missing data.</p>{/if}</div>
<div class="history"><h4>Across the nine selected emergencies</h4><p class="chart-note">Observed counts · {day?`Day ${day}`:'all three days'} · select a bar to filter the views above.</p><div class="event-bars">{#each summary.events as e}<button class:chosen-event={event===e.id} aria-pressed={event===e.id} aria-label={`Filter event ${e.id}`} on:click={() => event=event===e.id?'all':e.id}><span>{e.id}<small>{e.season}</small></span><span class="rail"><span style={`width:${countInScope(chosen.feature.properties,e.id,day)/maxEvent*100}%`}></span></span><b>{countInScope(chosen.feature.properties,e.id,day)}</b></button>{/each}</div></div>
<div class="phases"><h4>Three-day profile</h4><p class="chart-note">{event==='all'?'All 9 events':event} · select a phase.</p>{#each [1,2,3] as d}<button class:active-phase={day===d} aria-pressed={day===d} on:click={() => day=day===d?0:d}><span>Day {d}</span><strong>{countInScope(chosen.feature.properties,event,d)}</strong><small>observed records</small></button>{/each}<p class="detail-note">Event and day filters apply to the map, scatterplot and selected-neighborhood measures.</p></div></div>{/if}</article>
{/if}</section>
{#if geography}<ContextLens {geography} {selected} />{/if}
<section id="methods" class="methods"><div><p class="kicker">04 / WHAT THIS PROTOTYPE CAN TELL US</p><h2>Association is a question.<br />Causation needs more evidence.</h2><p>The current views connect place, event, emergency phase, population, income distribution, housing tenure, vehicle access and residential sales. They support exploration of neighborhood patterns.</p><a class="source-link" href="https://github.com/QinyangTan/minneapolis-snow-emergency-tows/tree/main/datasetsForFP2">Open the complete dataset catalog ↗</a><a class="source-link" href={`${base}/data/fp2-context.json`} download>Download the plotted neighborhood context ↓</a></div><div class="method-notes"><details open><summary>Coverage &amp; denominators</summary><p>The original nine-event baseline contains 5,423 records; 5,355 map to 87 neighborhoods and 68 do not. This is a selected sample. Zero means no record in this sample, not no towing ever. Population scaling uses 2020–2024 ACS residents, not parked vehicles or daily visitors. 86 neighborhood names match the city ACS extracts; Humboldt Industrial Area has no matched estimate.</p></details><details><summary>Income, housing &amp; uncertainty</summary><p>Economic indicators use ACS 2019–2023, while housing and population use ACS 2020–2024. They are overlapping five-year estimates, not event-time measurements. Source margins of error and reliability appear in the neighborhood detail; Spearman ρ does not propagate this uncertainty or adjust for spatial dependence. Per-capita income is shown at its native census tract scale in the context view; allocating it to neighborhoods is deferred.</p><p>Sale medians use 1,472 qualifying transactions from 2024; 54 neighborhoods have at least 10. They reflect the mix of homes sold, not every home's value. Missing or suppressed indicators are excluded from the scatterplot, never zero-filled.</p></details><details><summary>Why no ordinary-day comparison yet?</summary><p>A complete public Minneapolis actual-towing log with reason codes was not verified. 311 requests, 911 calls, citations and crashes are not completed tows. Citywide annual category totals cannot supply neighborhood ordinary-day counts, so that comparison is deferred. Traffic and per-capita income are available in the additional context view. Transit, weather and parking archives are saved for further event-aligned analysis.</p></details><details><summary>FP2 narrative &amp; next validation</summary><p>The three steps above move from geographic concentration to population adjustment and then contextual association. Selection persists across coordinated views; event/day changes test whether a pattern is stable. The next stage can animate transitions between the same views while preserving scales and respecting reduced-motion preferences.</p><p>Before a stronger claim: audit baseline source coverage, align event-time parking exposure and traffic, check spatial boundaries, propagate ACS uncertainty, and obtain actual towing reasons. Peer feedback: does population adjustment help? Which parking-exposure denominator is defensible? Are sparse or uncertain estimates clear?</p></details></div></section>
</main><footer><span>MINNEAPOLIS / SNOW EMERGENCY TOWS</span><span>FP2 · Exploratory research prototype · Sources captured November 2026</span></footer></div>
<style>
